import React, { useRef, useState, useEffect } from "react";

export default function ConceptBoard() {
  const boardRef = useRef(null);
  const fileInputRef = useRef(null);

  const [images, setImages] = useState([]);
  const [draggingId, setDraggingId] = useState(null);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const [transform, setTransform] = useState({ scale: 1, x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });

  const handleMouseDown = (e, id) => {
    e.stopPropagation();
    const image = images.find((img) => img.id === id);
    setDraggingId(id);
    setDragOffset({ x: e.clientX - image.x, y: e.clientY - image.y });
  };

  const handleMouseMove = (e) => {
    if (draggingId) {
      setImages((prev) =>
        prev.map((img) =>
          img.id === draggingId
            ? { ...img, x: (e.clientX - dragOffset.x), y: (e.clientY - dragOffset.y) }
            : img
        )
      );
    } else if (isPanning) {
      setTransform((prev) => ({
        ...prev,
        x: prev.x + (e.clientX - panStart.x),
        y: prev.y + (e.clientY - panStart.y),
      }));
      setPanStart({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseUp = () => {
    setDraggingId(null);
    setIsPanning(false);
  };

  const handleWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY * -0.001;
    setTransform((prev) => ({
      ...prev,
      scale: Math.min(3, Math.max(0.2, prev.scale + delta)),
    }));
  };

  const handleBackgroundMouseDown = (e) => {
    if (e.button === 0) {
      setIsPanning(true);
      setPanStart({ x: e.clientX, y: e.clientY });
    }
  };

  const handleAddImageClick = () => {
    fileInputRef.current.click();
  };

  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = () => {
      const name = prompt("Enter a name for this image:");
      const category = prompt("Enter a category for this image:");

      setImages((prev) => [
        ...prev,
        {
          id: Date.now().toString(),
          src: reader.result,
          x: 100,
          y: 100,
          name: name || "Untitled",
          category: category || "Uncategorized",
          width: 200,
          height: 200,
        },
      ]);
    };
    reader.readAsDataURL(file);
    e.target.value = null; // Reset input
  };

  useEffect(() => {
    const board = boardRef.current;
    board.addEventListener("wheel", handleWheel, { passive: false });
    return () => board.removeEventListener("wheel", handleWheel);
  }, []);

  return (
    <div
      ref={boardRef}
      onMouseDown={handleBackgroundMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
      style={{
        position: "relative",
        width: "100%",
        height: "calc(100vh - 160px)",
        backgroundColor: "#1a1a1a",
        overflow: "hidden",
        cursor: isPanning ? "grabbing" : "grab",
      }}
    >
      <div style={{ position: "absolute", top: 10, left: 10, zIndex: 10 }}>
        <button
          onClick={handleAddImageClick}
          style={{
            background: "#00d1b2",
            border: "none",
            padding: "8px 16px",
            borderRadius: "6px",
            color: "#fff",
            cursor: "pointer",
            fontWeight: "bold",
          }}
        >
          + Add Image
        </button>
        <input
          ref={fileInputRef}
          type="file"
          accept="image/*"
          onChange={handleImageUpload}
          style={{ display: "none" }}
        />
      </div>

      <div
        style={{
          transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale})`,
          transformOrigin: "0 0",
          position: "absolute",
          top: 0,
          left: 0,
        }}
      >
        {images.map((img) => (
          <div
            key={img.id}
            style={{
              position: "absolute",
              left: img.x,
              top: img.y,
              width: img.width,
              height: img.height + 40,
              cursor: "move",
              userSelect: "none",
              background: "#2a2a2a",
              borderRadius: "8px",
              padding: "4px",
              boxShadow: "0 4px 16px rgba(0,0,0,0.4)",
            }}
            onMouseDown={(e) => handleMouseDown(e, img.id)}
          >
            <img
              src={img.src}
              alt={img.name}
              style={{
                width: "100%",
                height: img.height,
                objectFit: "cover",
                borderRadius: "4px",
                pointerEvents: "none",
              }}
              draggable={false}
            />
            <div style={{ color: "#fff", fontSize: "0.8rem", marginTop: "4px", textAlign: "center" }}>
              <strong>{img.name}</strong> <br />
              <span style={{ opacity: 0.7 }}>{img.category}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
